static inline uint64_t CAVM_RXGM_MMC_TX_INTERRUPT(uint64_t a)
{
    if (cavm_is_model(OCTEONTX_CN20KA) && (a<=1))
        return 0x826000000808ll + 0x1000000000ll * ((a) & 0x1);
    __cavm_csr_fatal("RXGM_MMC_TX_INTERRUPT", 1, a, 0, 0, 0, 0, 0);
}

